corrected_code:
io.on('connection', (socket) => {
  socket.on('spectate_terminal', async ({ instanceId }) => {
    const instance = await CloudServer.findOne({ where: { id: instanceId, accountId: socket.data.accountId } });
    if (!instance) {
      return socket.emit('error', { message: 'Access denied: unassigned cloud server terminal' });
    }
    socket.join(`terminal:${instanceId}`);
    socket.emit('spectate_ready', { instanceId });
  });
});
